package com.vynedam.stockai.service; import com.vynedam.stockai.domain.PurchaseOrderStatus; import com.vynedam.stockai.dto.OperationsDtos.*; import com.vynedam.stockai.exception.ApiException; import com.vynedam.stockai.model.PurchaseOrder; import com.vynedam.stockai.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service;
@Service public class PurchaseOrderService{private final PurchaseOrderRepository orders;private final SupplierRepository suppliers;private final MaterialRepository materials;public PurchaseOrderService(PurchaseOrderRepository o,SupplierRepository s,MaterialRepository m){orders=o;suppliers=s;materials=m;}public List<PurchaseOrder>list(){return orders.findAll();}public PurchaseOrder create(PurchaseOrderRequest r,String user){suppliers.findById(r.supplierId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Supplier not found"));var po=new PurchaseOrder();po.poNumber="PO-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();po.supplierId=r.supplierId();po.status=PurchaseOrderStatus.DRAFT;po.createdBy=user;po.lines=r.lines().stream().map(x->{materials.findById(x.materialId()).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Material not found"));var l=new PurchaseOrder.Line();l.materialId=x.materialId();l.quantity=x.quantity();l.unitPrice=x.unitPrice();return l;}).toList();return orders.save(po);}public PurchaseOrder status(String id,PurchaseOrderStatus status){var po=orders.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND","Purchase order not found"));po.status=status;return orders.save(po);}}
